stds=np.array([(0.5 if 0<j<10 else 1/np.sqrt(12)) if k is None else np.sqrt((high[j]-k)**3/(3*span[j]**3)-((high[j]-k)**2/(2*span[j]**2))**2) for j,k in bs])
def features(X):
 B=np.array([X[:,j]/span[j] if k is None else np.maximum(X[:,j]-k,0)/span[j] for j,k in bs]).T
 B=(B-means)/stds
 return np.column_stack([np.ones(len(X)),B,B[:,ia]*B[:,ib]])
